INSERT INTO site_settings (id, brand, hero, sections, contact, content) VALUES (1, '{"name":"Viral Zoom","accent":"#69499e","logo":"/media/viral-zoom-logo.svg","whiteLogo":"/media/viral-zoom-logo-white.svg"}', '{"title":{"en":"Creative & Digital Marketing","ar":"الإبداع والتسويق الرقمي"},"subtitle":{"en":"Ideas that make your brand impossible to ignore.","ar":"أفكار تجعل علامتك التجارية مستحيلة التجاهل."},"video":"/media/video/social-campaign-reel.mp4","poster":""}', '{"services":false,"portfolio":true,"clients":true,"process":true,"banner":true,"contact":true}', '{"email":"info@viralzoom.com","phone":"","whatsapp":"","address":{"en":"Cairo, Egypt","ar":"القاهرة، مصر"}}', '{"about":{"seoTitle":{"en":"About Viral Zoom — Creative & Digital Agency","ar":"عن فايرال زوم — وكالة إبداعية ورقمية"},"seoDescription":{"en":"Meet Viral Zoom, a creative and digital agency combining strategy, design and technology to help brands grow.","ar":"تعرف على فايرال زوم، وكالة إبداعية ورقمية تجمع الاستراتيجية والتصميم والتكنولوجيا لتنمية العلامات التجارية."},"heroEyebrow":{"en":"ABOUT VIRAL ZOOM","ar":"عن فايرال زوم"},"heroTitle":{"en":"We turn bold ideas","ar":"نحوّل الأفكار"},"heroTitleAccent":{"en":"into real impact.","ar":"الجريئة لتأثير حقيقي."},"heroDescription":{"en":"We are a creative and digital agency bringing strategy, design and technology together to help brands move forward.","ar":"إحنا وكالة إبداعية ورقمية بنجمع الاستراتيجية والتصميم والتكنولوجيا عشان نساعد العلامات التجارية تتقدم."},"heroCta":{"en":"Get to know us","ar":"اعرفنا أكتر"},"heroImageAlt":{"en":"A creative digital project by Viral Zoom","ar":"مشروع رقمي إبداعي من فايرال زوم"},"heroCaption":{"en":"Ideas made visible","ar":"أفكار تتحول لواقع"},"storyEyebrow":{"en":"WHO WE ARE","ar":"مين إحنا"},"storyTitle":{"en":"A creative partner for brands ready to grow.","ar":"شريك إبداعي للعلامات اللي مستعدة تكبر."},"storyParagraphs":[{"en":"At Viral Zoom, we bring creative services and digital solutions together under one roof. From brand identity and content to websites, campaigns and production, we help shape consistent experiences that connect with people.","ar":"في فايرال زوم، بنجمع الخدمات الإبداعية والحلول الرقمية في مكان واحد. من الهوية والمحتوى للمواقع والحملات والإنتاج، بنساعد في بناء تجارب متناسقة تقرّب علامتك من جمهورها."},{"en":"Every project starts with understanding what makes your business different. Then we turn that understanding into clear ideas, thoughtful design and work made to support your next step.","ar":"كل مشروع بيبدأ بفهم اللي بيميّز شغلك. بعدها نحوّل الفهم لأفكار واضحة وتصميم مدروس وشغل يساعدك تاخد خطوتك الجاية."}],"storyCta":{"en":"Explore selected projects","ar":"شوف مشاريعنا"},"valuesEyebrow":{"en":"HOW WE THINK","ar":"طريقة تفكيرنا"},"valuesTitle":{"en":"Creative with purpose.","ar":"إبداع له هدف."},"valuesDescription":{"en":"Good work is more than a good-looking idea. It should make sense for your brand and move you toward a goal.","ar":"الشغل الحلو مش مجرد شكل جذاب؛ لازم يناسب علامتك ويقرّبك من هدفك."},"values":[{"title":{"en":"Start with insight","ar":"نبدأ بالفهم"},"text":{"en":"We learn about your brand, your audience and your goals before shaping the right direction.","ar":"نفهم علامتك وجمهورك وأهدافك قبل ما نحدد الاتجاه المناسب."}},{"title":{"en":"Make ideas matter","ar":"نحوّل الأفكار لتأثير"},"text":{"en":"We bring creative thinking and practical strategy together to make every touchpoint count.","ar":"نجمع بين الإبداع والاستراتيجية العملية عشان كل نقطة تواصل يكون ليها أثر."}},{"title":{"en":"Build for progress","ar":"نبني للتطور"},"text":{"en":"We test, learn and refine the work, keeping the focus on meaningful progress for your brand.","ar":"نختبر ونتعلم ونطوّر شغلنا، مع تركيزنا على تقدم حقيقي لعلامتك التجارية."}}],"approachEyebrow":{"en":"OUR APPROACH","ar":"منهجيتنا"},"approachTitle":{"en":"Think clearly. Create boldly. Keep growing.","ar":"فكّر بوضوح. ابتكر بجرأة. واستمر في التطور."},"approachDescription":{"en":"We work through a clear cycle: understand the opportunity, create and test ideas, learn from what happens, then build on what works.","ar":"بنتبع خطوات واضحة: نفهم الفرصة، نبتكر ونختبر الأفكار، نتعلم من النتائج، وبعدها نطوّر اللي أثبت نجاحه."},"ctaEyebrow":{"en":"LET''S BUILD WHAT''S NEXT","ar":"يلا نبدأ خطوتك الجاية"},"ctaTitle":{"en":"Have an idea in mind?","ar":"عندك فكرة في بالك؟"},"ctaDescription":{"en":"Tell us what you are working toward. We would love to hear about it.","ar":"احكيلنا عن هدفك، ويسعدنا نسمع فكرتك."},"ctaButton":{"en":"Start a conversation","ar":"ابدأ كلامنا"}},"process":{"eyebrow":{"en":"THE VIRAL ZOOM METHOD","ar":"منهجية فايرال زوم"},"title":{"en":"Measure. Ideate. Experiment. Read. Scale.","ar":"حلّل. ابتكر. جرّب. قيّم. وسّع."},"intro":{"en":"A clear, repeatable process for meaningful results.","ar":"خطوات واضحة ومتكررة لتحقيق نتائج مؤثرة."},"steps":[{"name":{"en":"Measure","ar":"حلّل"},"description":{"en":"Find the opportunity.","ar":"نكتشف الفرص المناسبة."}},{"name":{"en":"Ideate","ar":"ابتكر"},"description":{"en":"Turn insight into ideas.","ar":"نحوّل الرؤى إلى أفكار."}},{"name":{"en":"Experiment","ar":"جرّب"},"description":{"en":"Create. Test. Iterate.","ar":"نبتكر، نختبر، ونطوّر."}},{"name":{"en":"Read","ar":"حلّل النتائج"},"description":{"en":"Learn what works.","ar":"نتعلّم مما يحقق النتائج."}},{"name":{"en":"Scale","ar":"وسّع"},"description":{"en":"Do more of what works.","ar":"نوسّع أثر ما ينجح."}}]},"seo":{"siteTitle":{"en":"Viral Zoom","ar":"فايرال زوم"},"siteDescription":{"en":"Creative and digital marketing agency.","ar":"وكالة إبداعية ورقمية للتسويق والتصميم."},"homeTitle":{"en":"Creative & Digital Marketing | Viral Zoom","ar":"الإبداع والتسويق الرقمي | فايرال زوم"},"homeDescription":{"en":"Ideas that make your brand impossible to ignore.","ar":"أفكار تجعل علامتك التجارية مستحيلة التجاهل."},"servicesTitle":{"en":"Our Services | Viral Zoom","ar":"خدماتنا | فايرال زوم"},"projectsTitle":{"en":"Our Projects | Viral Zoom","ar":"أعمالنا | فايرال زوم"},"contactTitle":{"en":"Contact Viral Zoom","ar":"تواصل مع فايرال زوم"}}}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'website-design', 0, '{"id":"website-design","name":{"en":"Website Design","ar":"تصميم مواقع إلكترونية"},"description":{"en":"Viral Zoom plans and designs fast, responsive business websites with clear navigation, accessible layouts and content tailored to your customers. We work from your goals and brand identity through launch, helping Egyptian and Arab businesses turn visits into enquiries.","ar":"تصمم فايرال زوم مواقع شركات سريعة ومتوافقة مع الجوال، بهيكل واضح ومحتوى يناسب جمهورك. نبدأ من أهداف نشاطك وهويته ونرافقك حتى الإطلاق، لمساعدة الشركات في مصر والمنطقة العربية على تحويل الزيارات إلى استفسارات."},"image":"/media/campaign/social-02.webp","link":"/services/website-design","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'ecommerce-development', 1, '{"id":"ecommerce-development","name":{"en":"E-commerce Development","ar":"تطوير المتاجر الإلكترونية"},"description":{"en":"We build online stores with mobile-first product pages, straightforward browsing and a checkout flow designed around your catalogue and operations. From store structure to launch, we help businesses in Egypt and the Arab region sell online with a consistent brand experience.","ar":"نطور متاجر إلكترونية بصفحات منتجات مناسبة للموبايل وتصفح واضح وخطوات شراء مبنية على طبيعة منتجاتك وتشغيلك. من تنظيم المتجر إلى إطلاقه، نساعد الشركات في مصر والمنطقة العربية على البيع أونلاين بتجربة متناسقة مع علامتها."},"image":"/media/campaign/social-02.webp","link":"/services/ecommerce-development","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'digital-marketing', 2, '{"id":"digital-marketing","name":{"en":"Digital Marketing","ar":"التسويق الرقمي"},"description":{"en":"Our digital marketing service connects content, social media, search and paid campaigns to business goals. We plan audience-focused activity, create useful brand content and use campaign reporting to identify what to improve for Egyptian, Saudi and wider Gulf audiences.","ar":"نربط في خدمة التسويق الرقمي بين المحتوى والسوشيال ميديا والبحث والإعلانات المدفوعة وبين أهداف النشاط التجاري. نخطط لحملات تناسب الجمهور وننتج محتوى مفيدًا ونتابع النتائج لتحسينها في مصر والسعودية وأسواق الخليج."},"image":"/media/campaign/social-07.webp","link":"/services/digital-marketing","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'software-development', 3, '{"id":"software-development","name":{"en":"Software Development","ar":"تطوير البرمجيات"},"description":{"en":"We design and develop custom web platforms and business software around real workflows, user needs and integration requirements. Viral Zoom supports teams from requirements and interface planning through implementation and launch for projects in Egypt and the Arab region.","ar":"نصمم ونطور منصات ويب وبرمجيات أعمال مخصصة حسب سير العمل واحتياجات المستخدم ومتطلبات التكامل. تدعم فايرال زوم الفرق من تحديد المتطلبات وتخطيط الواجهات إلى التنفيذ والإطلاق للمشروعات في مصر والمنطقة العربية."},"image":"/media/campaign/social-03.webp","link":"/services/software-development","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'printing', 4, '{"id":"printing","name":{"en":"Printing","ar":"الطباعة"},"description":{"en":"We offer premium printing services that bring your marketing materials to life with unmatched quality. From stunning brochures and posters to custom business cards and promotional products, our advanced printing techniques ensure vibrant, sharp, and professional results. We understand the power of well-crafted print to leave a lasting impression, and our team is committed to delivering materials that enhance your brand’s presence. Whether you''re looking to captivate clients or boost brand awareness, our printing solutions are designed to make your message stand out.","ar":"نقدم خدمات طباعة عالية الجودة تمنح موادك التسويقية حضورًا مميزًا. من البروشورات والبوسترات إلى كروت الأعمال والمنتجات الدعائية، نهتم بكل تفصيلة لتصل رسالة علامتك التجارية بأفضل صورة."},"image":"/media/campaign/social-05.webp","link":"/services/printing","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'seo', 5, '{"id":"seo","name":{"en":"SEO","ar":"تحسين محركات البحث"},"description":{"en":"We specialize in expert SEO services designed to improve your website’s visibility and drive organic traffic. Our tailored strategies focus on optimizing your content, enhancing site performance, and building quality backlinks to help you rank higher on search engines. With our data-driven approach, we ensure your brand reaches the right audience at the right time. From keyword research to on-page optimization, our SEO solutions are crafted to deliver long-term results and boost your online presence, helping you stay ahead of the competition and grow your business.","ar":"نساعد موقعك على الظهور أمام الجمهور المناسب وزيادة الزيارات الطبيعية. نعمل على تحسين المحتوى وأداء الموقع، ودراسة الكلمات المفتاحية وبناء روابط قوية لتحقيق نتائج مستدامة."},"image":"/media/campaign/meta-sample-01.webp","link":"/services/seo","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'events-management', 6, '{"id":"events-management","name":{"en":"Events Management","ar":"إدارة الفعاليات"},"description":{"en":"We offer expert event management services that turn your vision into a seamless, unforgettable experience. Whether it’s a corporate conference, product launch, or private celebration, our team handles every detail—planning, logistics, coordination, and execution—ensuring flawless events from start to finish. We focus on creating engaging, memorable experiences that align with your brand’s goals and leave a lasting impact on your audience. Let us take care of the details so you can focus on what matters most: connecting with your guests and achieving your event objectives.","ar":"نحوّل رؤيتك إلى تجربة متكاملة لا تُنسى. من المؤتمرات وإطلاق المنتجات إلى المناسبات الخاصة، نتولى التخطيط والتنظيم والتنسيق والتنفيذ، لتتفرغ للتواصل مع ضيوفك."},"image":"/media/campaign/social-08.webp","link":"/services/events-management","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'animation-video', 7, '{"id":"animation-video","name":{"en":"Animation Video","ar":"فيديوهات الأنيميشن"},"description":{"en":"We create captivating animation videos that bring your ideas to life in a visually engaging way. From explainer videos to promotional animations, our team blends creativity with storytelling to produce content that resonates with your audience. With dynamic visuals and compelling narratives, we craft animations that simplify complex messages and capture attention. Whether for social media, websites, or advertisements, our animation videos are designed to elevate your brand, boost engagement, and leave a lasting impression.","ar":"نحوّل أفكارك إلى فيديوهات أنيميشن جذابة تجمع الإبداع بالحكاية. نصنع فيديوهات توضيحية وإعلانية تبسّط الرسائل وتلفت الأنظار وتعزز تفاعل جمهورك مع علامتك التجارية."},"image":"/media/campaign/social-03.webp","link":"/services/animation-video","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'website-creation', 8, '{"id":"website-creation","name":{"en":"Website Creation","ar":"تصميم المواقع"},"description":{"en":"We specialize in creating stunning, user-friendly websites that not only look great but also drive results. Our team of designers and developers work closely with you to build a customized website that reflects your brand’s identity and meets your business goals. From responsive design to seamless functionality, we ensure your site provides an exceptional user experience across all devices. Whether you''re looking for an e-commerce platform, a portfolio, or a corporate site, we deliver websites that engage visitors and convert them into loyal customers.","ar":"نصمم مواقع عصرية وسهلة الاستخدام تعكس هوية علامتك وتحقق أهدافك. من المتاجر الإلكترونية إلى مواقع الشركات ومعارض الأعمال، نقدم تجربة متكاملة على جميع الأجهزة."},"image":"/media/campaign/social-02.webp","link":"/services/website-creation","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'video-production', 9, '{"id":"video-production","name":{"en":"Video Production","ar":"إنتاج الفيديو"},"description":{"en":"We turn ideas into video content that reflects your brand and connects with your audience.","ar":"نحول الأفكار إلى محتوى فيديو يعكس هوية علامتك التجارية ويصل إلى جمهورك."},"image":"/media/video/social-campaign-poster.jpg","link":"/services/video-production","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'social-media-management', 10, '{"id":"social-media-management","name":{"en":"Social Media Management","ar":"إدارة السوشيال ميديا"},"description":{"en":"We provide expert social media management to help your brand thrive in today’s digital world. Our team creates tailored strategies that drive engagement, build community, and boost brand visibility across platforms like Instagram, Facebook, LinkedIn, and more. From content creation and scheduling to community management and analytics, we handle every aspect of your social media presence. With a data-driven approach and creative expertise, we ensure your brand stays relevant, connects with the right audience, and achieves measurable results.","ar":"نضع استراتيجيات مخصصة لحضور علامتك على إنستجرام وفيسبوك ولينكدإن وغيرها. من صناعة المحتوى وجدولته إلى إدارة المجتمع وتحليل النتائج، نهتم بكل تفاصيل حضورك الرقمي."},"image":"/media/campaign/social-07.webp","link":"/services/social-media-management","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'offline-marketing', 11, '{"id":"offline-marketing","name":{"en":"Offline Marketing","ar":"التسويق الميداني"},"description":{"en":"We believe in the power of offline marketing to create lasting, personal connections with your audience. From print advertisements and direct mail campaigns to event marketing and experiential activations, our team develops strategies that engage customers in the real world. We craft meaningful, memorable experiences that drive brand awareness and loyalty. By combining creative design with strategic planning, we help you reach your target audience through impactful, offline channels that complement your digital efforts and leave a tangible impression.","ar":"نصنع تواصلًا حقيقيًا مع جمهورك من خلال الإعلانات المطبوعة والفعاليات والتجارب الميدانية. نمزج التخطيط والإبداع لنقدم حملات ملموسة تدعم حضورك الرقمي وتبني ولاء العملاء."},"image":"/media/campaign/social-05.webp","link":"/services/offline-marketing","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'google-ads', 12, '{"id":"google-ads","name":{"en":"Google Ads","ar":"إعلانات جوجل"},"description":{"en":"We specialize in Google Ads campaigns that drive targeted traffic and generate measurable results. Our team optimizes every aspect of your campaign—from keyword research and ad creation to bid management and performance tracking. With a focus on maximizing ROI, we ensure your ads reach the right audience at the right time, whether you’re looking to increase website visits, drive conversions, or boost brand awareness. Let us help you leverage the power of Google Ads to grow your business and achieve your marketing goals.","ar":"نصمم حملات إعلانات جوجل التي تصل إلى الجمهور المناسب وتحقق نتائج قابلة للقياس. نهتم بالكلمات المفتاحية والإعلانات والميزانية ومتابعة الأداء لزيادة الزيارات والتحويلات."},"image":"/media/campaign/meta-sample-01.webp","link":"/services/google-ads","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('services', 'games-development', 13, '{"id":"games-development","name":{"en":"Games Development","ar":"تطوير الألعاب"},"description":{"en":"We specialize in game development that blends creativity, technology, and innovation to deliver immersive and engaging experiences. Whether it''s mobile games, interactive apps, or custom-branded games, our team of developers, designers, and storytellers work together to bring your vision to life. We focus on creating high-quality, visually captivating games that captivate your audience and keep them coming back for more. With a user-centric approach, we ensure each game is optimized for maximum engagement, providing both entertainment and value to your brand.","ar":"نمزج الإبداع والتكنولوجيا لصناعة ألعاب وتجارب تفاعلية ممتعة. نطور ألعاب الهاتف وتطبيقات تفاعلية وألعابًا مخصصة للعلامات التجارية، مع التركيز على جودة التصميم وتجربة المستخدم."},"image":"/media/campaign/social-03.webp","link":"/services/games-development","enabled":true}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('projects', 'bio-derma-group', 0, '{"id":"bio-derma-group","name":{"en":"Bio Derma Group","ar":"Bio Derma Group"},"description":{"en":"A visual identity project created to give Bio Derma Group a clear, consistent presence across its brand touchpoints.","ar":"مشروع هوية بصرية يمنح Bio Derma Group حضورًا واضحًا ومتناسقًا عبر مختلف نقاط التواصل مع الجمهور."},"image":"/media/campaign/social-01.webp","link":"/projects/bio-derma-group","enabled":true,"projectCategory":"branding","projectKind":"case-study"}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('projects', 'sarhan-obesity-clinic', 1, '{"id":"sarhan-obesity-clinic","name":{"en":"DR. Mohamed Diaa Sarhan (Sarhan Obesity Clinic)","ar":"DR. Mohamed Diaa Sarhan (Sarhan Obesity Clinic)"},"description":{"en":"A brand identity direction for Sarhan Obesity Clinic, designed to communicate a professional and recognizable healthcare brand.","ar":"تصميم هوية بصرية لعيادة د. محمد ضياء سرحان، تعكس صورة احترافية وسهلة التميّز للعلامة الطبية."},"image":"/media/campaign/social-02.webp","link":"/projects/sarhan-obesity-clinic","enabled":true,"projectCategory":"branding","projectKind":"case-study"}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('projects', 'egy-marks', 2, '{"id":"egy-marks","name":{"en":"Egy Marks","ar":"Egy Marks"},"description":{"en":"A brand identity project for Egy Marks, bringing its visual language together in a distinctive and consistent presentation.","ar":"مشروع هوية بصرية لـ Egy Marks يجمع عناصر العلامة في تقديم مميز ومتناسق."},"image":"/media/campaign/social-03.webp","link":"/projects/egy-marks","enabled":true,"projectCategory":"branding","projectKind":"case-study"}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('projects', 'el-masia-pack', 3, '{"id":"el-masia-pack","name":{"en":"El Masia Pack","ar":"El Masia Pack"},"description":{"en":"A visual identity project for El Masia Pack, built to help the brand present itself consistently across its materials.","ar":"مشروع هوية بصرية لـ El Masia Pack يساعد العلامة على الظهور بشكل متناسق عبر موادها المختلفة."},"image":"/media/campaign/social-04.webp","link":"/projects/el-masia-pack","enabled":true,"projectCategory":"branding","projectKind":"case-study"}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('projects', 'feedmix', 4, '{"id":"feedmix","name":{"en":"Feedmix","ar":"Feedmix"},"description":{"en":"A brand identity project for Feedmix, with a cohesive visual direction for its brand communications.","ar":"مشروع هوية بصرية لـ Feedmix مع توجه بصري متناسق للتواصل مع جمهور العلامة."},"image":"/media/campaign/social-05.webp","link":"/projects/feedmix","enabled":true,"projectCategory":"branding","projectKind":"case-study"}');
INSERT INTO content_items (collection, item_id, position, content) VALUES ('projects', 'el-fayrouz', 5, '{"id":"el-fayrouz","name":{"en":"El Fayrouz","ar":"El Fayrouz"},"description":{"en":"A visual identity project for El Fayrouz, presenting the brand through a clear and unified look.","ar":"مشروع هوية بصرية لـ El Fayrouz يقدم العلامة بشكل واضح وموحّد."},"image":"/media/campaign/social-06.webp","link":"/projects/el-fayrouz","enabled":true,"projectCategory":"branding","projectKind":"case-study"}');
