/media/video/social-campaign-reel.mp4","videoPoster":"/media/video/social-campaign-poster.jpg","communityGrowth":[{"platform":"TikTok","followers":"+125K","label":{"en":"new followers","ar":"متابع جديد"}},{"platform":"Instagram","followers":"+98K","label":{"en":"new followers","ar":"متابع جديد"}},{"platform":"Snapchat","followers":"+72K","label":{"en":"new followers","ar":"متابع جديد"}}]}}');
